-- gap cmp:223:41:2, written by an automated writer
test("breakit Drive.Bell: the crew hello names at most six people", function()
	local w = T.newWorld()
	local names = { T.BEA, T.CAL, "Dan Miller", "Eve Long", "Fay Moss", "Gus Reed" }
	local crew = {}
	for _, n in ipairs(names) do crew[#crew + 1] = { name = n, role = "lock", app = true } end
	local ana = w:addClient(T.ANA, { spot = "Undercity", class = "WARLOCK", saved = { Wuber = { chars = {
		["ana smith"] = { crew = crew, captain = "", wizard = true } } } } })
	local group = { T.ANA }
	for _, n in ipairs(names) do
		w:addBot(n, { spot = "Undercity", class = "WARLOCK" })
		group[#group + 1] = n
	end
	w:addClient("Wuber Rocks", { spot = "Orgrimmar", class = "MAGE" })
	w:group(group)
	T.settle(w)
	ana.W.Drive.BellSet("Wuber Rocks")
	w:advance(3)
	local list
	for _, e in ipairs(w.addonLog) do
		if e.prefix == "WUBERT" and e.from == T.ANA and type(e.text) == "string" and e.text:sub(1, 3) == "BH~" then
			list = T.fields(e)[4]
		end
	end
	ok(list, "Ana's window tells the alert character who the crew is")
	eq(select(2, list:gsub(",", "")), 5, "six names fit in the crew hello: " .. tostring(list))
	ok(not list:lower():find("gus reed", 1, true), "the seventh name is left out: " .. tostring(list))
	T.clean(w)
end)

